import {guidedWeekly} from './workshop-repair-guided-weekly.mjs';
import {readGuidedGoal,repairDay} from './workshop-repair-guided-review.mjs';
export function mountGuidedWeekly({language,host,interventionName,launch,available,hidden=()=>false}){
 const root=document.createElement('section');root.id='guidedRepairWeekly';root.className='challenge-panel';host.before(root);let lastRows=[];
 const t=(es,en)=>language()==='es'?es:en,date=day=>new Date(day+'T12:00:00Z').toLocaleDateString(language(),{timeZone:'UTC',day:'numeric',month:'short',year:'numeric'});
 function render(rows=lastRows){lastRows=rows;root.hidden=hidden();if(root.hidden)return;let goal=2,goalError=false;try{goal=readGuidedGoal(localStorage);}catch{goalError=true;}const s=guidedWeekly(rows,goal);root.replaceChildren();const add=(tag,text,parent=root)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};const practice=(entry,parent)=>{const b=add('button',t('Practicar en 3D','Practise in 3D'),parent);b.dataset.weeklyGuided=entry.key;b.disabled=!available();b.onclick=()=>launch(entry);};
 add('h2',t('Tu semana de reparaciones guiadas','Your guided repair week'));add('p',date(s.start)+' – '+date(s.today)+' · Bogotá');
 const metrics=add('div','');metrics.className='repair-weekly-metrics';for(const [label,value]of [[t('Prácticas guiadas completadas','Completed guided practices'),s.current.count],[t('Nota media','Average score'),s.current.average===null?'—':s.current.average+'/100'],[t('Días de práctica','Practice days'),s.current.days],[t('Racha actual','Current streak'),s.streak]]){const card=add('article','',metrics);add('strong',String(value),card);add('p',label,card);}
 add('p',t('Comparación con ','Compared with ')+date(s.priorStart)+' – '+date(s.priorEnd)+': '+(s.delta===null?t('faltan resultados en uno de los períodos.','one period has no results yet.'):(s.delta>0?'+':'')+s.delta+t(' puntos de nota media.',' average-score points.')));add('p',t('Semana anterior, mismos días: ','Previous week, same weekdays: ')+s.previous.count+t(' prácticas · media ',' practices · average ')+(s.previous.average===null?'—':s.previous.average+'/100'));
 add('p',s.current.hints+t(' pistas · ',' hints · ')+s.current.unnecessary+t(' intervenciones innecesarias · ',' unnecessary interventions · ')+s.current.total+t(' decisiones esta semana.',' decisions this week.'));
 add('h3',t('Intervenciones que más te cuestan esta semana','Hardest interventions this week'));if(!s.hardest.length)add('p',s.current.count?t('Sin penalizaciones registradas esta semana. Sigue repasando para consolidar lo aprendido.','No recorded penalties this week. Keep reviewing to reinforce what you learned.'):t('Completa una práctica guiada para empezar tu resumen.','Complete a guided practice to start your summary.'));
 for(const g of s.hardest){const card=add('article','');card.className='repair-progress-card';add('h4',interventionName(g),card);add('p',g.wrong+'/'+g.total+t(' elecciones innecesarias · ',' unnecessary choices · ')+g.hints+t(' pistas',' hints'),card);practice(g,card);}
 add('h3',t('Plan para la próxima semana','Next week’s review plan'));add('p',date(s.plan.start)+' – '+date(s.plan.end));add('p',t('Hasta ','Up to ')+s.plan.capacity+t(' retos por día, según tu meta diaria. Primero las intervenciones vencidas con mayor proporción de errores, y luego las que requieren más pistas. Cada intervención aparece una vez; el plan se recalcula al practicar. Puedes adelantar un reto.',' challenges per day, based on your daily goal. Due interventions with higher error rates come first, followed by those needing more hints. Each intervention appears once; the plan updates with practice. You can practise a challenge early.'));
 if(goalError)add('p',t('No se pudo leer la meta; se usa 2 para este plan.','Could not read the goal; this plan uses 2.'));
 const plan=add('div','');plan.className='repair-weekly-plan';for(const day of s.plan.days){const card=add('article','',plan);add('h4',date(day.day),card);if(!day.entries.length)add('p',t('Sin retos previstos. Se actualizará al practicar.','No challenges planned. Updates with practice.'),card);for(const entry of day.entries){add('p',interventionName(entry)+' · '+entry.wrong+'/'+entry.total+t(' elecciones innecesarias · ',' unnecessary choices · ')+t('Vencimiento original: ','Original due date: ')+date(entry.due),card);practice(entry,card);}}
 add('p',s.plan.scheduled+t(' retos previstos · ',' planned challenges · ')+s.plan.backlog+t(' pendientes sin espacio esta semana.',' due reviews beyond this week’s capacity.'));
 add('p',t('Resumen basado en las últimas 100 prácticas guiadas completadas. La racha es exclusiva de este modo. Las medias dependen de los casos y niveles practicados; no son una prueba de dominio. El plan es provisional y no supone que ya hayas completado los retos futuros.','Summary uses the latest 100 completed guided practices. The streak belongs to this mode only. Average scores depend on the cases and levels practised; they are not proof of mastery. The plan is provisional and does not assume future challenges are completed.'));if(!available())add('p',t('Abre un examen completado para acceder a los bancos de reparación.','Open a completed exam to access the repair benches.'));
 }
 let day=repairDay();setInterval(()=>{if(day!==repairDay()){day=repairDay();render();}},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});return {render};
}
